import datetime
import math
import re
import polars as pl

NULL_VALUES = {"", "n/a", "N/A", "-", "null", "NULL"}


def _clean_str(col: pl.Expr) -> pl.Expr:
    return pl.when(col.str.to_lowercase().is_in(list(NULL_VALUES))).then(None).otherwise(col)


def transform(raw: pl.DataFrame) -> pl.DataFrame:
    return raw.select(
        supplier=_clean_str(pl.col("Supplier")),
        sku=_clean_str(pl.col("SKU")).str.to_uppercase(),
        description=_clean_str(pl.col("Description")),
        unit=_clean_str(pl.col("Unit")).str.to_uppercase(),
        pack_size=_clean_str(pl.col("Pack Size")).cast(pl.Int64, strict=False),
        price=_clean_str(pl.col("Price")).cast(pl.Float64, strict=False).round(2),
        currency=_clean_str(pl.col("Currency")).str.to_uppercase(),
        valid_from=_clean_str(pl.col("Valid From")).str.to_date("%Y-%m-%d", strict=False),
    )
